370:HeavyCoin::get_settings()
371-{
372-  auto result = MovingSprite::get_settings();
373-
374-  result.add_script(get_uid(), _("Collect script"), &m_collect_script, "collect-script");
375-
376-  result.reorder({"collect-script", "sprite", "x", "y"});
377-
378-  return result;
379-}
380-
381-void
382:HeavyCoin::after_editor_set()
383-{
384-  MovingSprite::after_editor_set();
385-}
