387-void
388:HeavyCoin::on_flip(float height)
389-{
390-  // Call on_flip from grandparent class MovingSprite to
391:  // avoid flipping of gravity-affected object HeavyCoin.
392-  MovingSprite::on_flip(height);
393-}

